with recursive paths as (select row_number() over(order by id) as n,fullkey||'.id' as path from json_tree(?1) where type='object' and json_extract(value,'$.kind')='paper' and json_extract(value,'$.id')=?2), replaced(n,doc) as (select 0,?1 union all select replaced.n+1,json_set(doc,paths.path,json(data_json_quote_v1(?3))) from replaced join paths on paths.n=replaced.n+1) select doc from replaced order by n desc limit 1